import{_ as o,o as d,c,ai as i}from"./chunks/framework.DAbPic9L.js";const u=JSON.parse('{"title":"速通 Vim","description":"","frontmatter":{},"headers":[],"relativePath":"disciplines/script/cmd/vim.md","filePath":"disciplines/script/cmd/vim.md","lastUpdated":1787215730000}'),l={name:"disciplines/script/cmd/vim.md"};function a(t,e,p,r,n,h){return d(),c("div",null,[...e[0]||(e[0]=[i('<h1 id="速通-vim" tabindex="-1">速通 Vim <a class="header-anchor" href="#速通-vim" aria-label="Permalink to &quot;速通 Vim&quot;">​</a></h1><p>文/晨风不可依米</p><br><h2 id="操作模式" tabindex="-1">操作模式 <a class="header-anchor" href="#操作模式" aria-label="Permalink to &quot;操作模式&quot;">​</a></h2><h3 id="命令模式" tabindex="-1">命令模式 <a class="header-anchor" href="#命令模式" aria-label="Permalink to &quot;命令模式&quot;">​</a></h3><p>默认模式；常用于文本选择、拷贝、粘贴等操作场景。</p><p>点击按下<code>esc</code>键，可进入该模式；其它模式操作应基于此进行切换。</p><h3 id="编辑模式" tabindex="-1">编辑模式 <a class="header-anchor" href="#编辑模式" aria-label="Permalink to &quot;编辑模式&quot;">​</a></h3><p>常用于文本编辑场景；窗体底部出现关键字<code>INSERT</code>。</p><p>按下<code>i</code>键进入该模式，可进行文本编辑。</p><h3 id="末行模式" tabindex="-1">末行模式 <a class="header-anchor" href="#末行模式" aria-label="Permalink to &quot;末行模式&quot;">​</a></h3><p>常用于文本检索、光标跳转、保存推出等操作场景。</p><p>按下<code>:</code>键进入该模式，可进行命令输入。</p><h2 id="光标命令" tabindex="-1">光标命令 <a class="header-anchor" href="#光标命令" aria-label="Permalink to &quot;光标命令&quot;">​</a></h2><ul><li><p>左下上右: <code>h j k l</code>。</p></li><li><p>单词前后: <code>b w</code>。</p></li><li><p>当行首尾: <code>0 $</code>。</p></li><li><p>文件头尾: <code>gg G</code>。</p></li><li><p>指定跳转: <code>:</code> + <code>n</code>；<code>n</code>为数字行数。</p></li><li><p>新行插入: <code>o O</code>。</p></li><li><p>翻页跳转: <code>Ctrl + u</code>为上一页 ， <code>Ctrl + d</code>为下一页。</p></li></ul><h2 id="文本命令" tabindex="-1">文本命令 <a class="header-anchor" href="#文本命令" aria-label="Permalink to &quot;文本命令&quot;">​</a></h2><ul><li><p>光标选择: <code>v</code>；<code>shift + v</code>为多行选择。</p></li><li><p>单词选择: <code>viw</code>。</p></li><li><p>单词删除: <code>diw</code>。</p></li><li><p>单词复制: <code>yiw</code>。</p></li><li><p>单词修改: <code>ciw</code>。</p></li><li><p>区块选择: <code>vip</code>；空格间隔内的所有内容。</p></li></ul><h2 id="拷贝粘贴" tabindex="-1">拷贝粘贴 <a class="header-anchor" href="#拷贝粘贴" aria-label="Permalink to &quot;拷贝粘贴&quot;">​</a></h2><ul><li><p>拷贝选中内容: <code>y</code>。</p></li><li><p>剪切选中内容: <code>d</code>。</p></li><li><p>修改选中内容: <code>c</code>；相当于删除并进入插入模式。</p></li><li><p>粘贴: <code>p</code>。</p></li><li><p>当行复制: <code>yy</code>。</p></li><li><p>指定行复制: <code>nyy</code>，<code>n</code>为行数。</p></li><li><p>当行剪切: <code>dd</code>。</p></li><li><p>当行修改: <code>cc</code>；相当于删除并进入插入模式。</p></li><li><p>切换档次大小写: <code>~</code>。</p></li></ul><h2 id="撤销恢复" tabindex="-1">撤销恢复 <a class="header-anchor" href="#撤销恢复" aria-label="Permalink to &quot;撤销恢复&quot;">​</a></h2><ul><li><p>撤销: <code>u</code>。</p></li><li><p>恢复: <code>Ctrl + r</code>。</p></li></ul><h2 id="查找命令" tabindex="-1">查找命令 <a class="header-anchor" href="#查找命令" aria-label="Permalink to &quot;查找命令&quot;">​</a></h2><ul><li><p>向下匹配查找: <code>/content</code>，<code>content</code>为匹配内容；配合<code>n N</code>匹配下一个或上一个。</p></li><li><p>向上匹配查找: <code>?content</code>，<code>content</code>为匹配内容；配合<code>n N</code>匹配下一个或上一个。</p></li></ul><h2 id="替换替换" tabindex="-1">替换替换 <a class="header-anchor" href="#替换替换" aria-label="Permalink to &quot;替换替换&quot;">​</a></h2><ul><li><p>单行替换: <code>:s/old/new/g</code>；<code>old</code>为匹配内容，<code>new</code>为替换内容；<code>g</code>为全局替换。</p></li><li><p>范围替换: <code>:&lt;start,end&gt;s/old/new/g</code>；<code>start</code>为开始行，<code>end</code>为结束行；<code>old</code>为匹配内容，<code>new</code>为替换内容；<code>g</code>为全局替换。</p></li><li><p>全文替换: <code>:%s/old/new/gc</code>；<code>old</code>为匹配内容，<code>new</code>为替换内容，<code>%</code>为全文匹配，<code>g</code>为全局替换，<code>c</code>为交互确认。</p></li></ul><h2 id="保存命令" tabindex="-1">保存命令 <a class="header-anchor" href="#保存命令" aria-label="Permalink to &quot;保存命令&quot;">​</a></h2><ul><li><p>保存: <code>:w</code>。</p></li><li><p>退出: <code>:q</code>。</p></li><li><p>保存并退出: <code>:wq</code>。</p></li><li><p>不保存退出: <code>:q!</code>。</p></li></ul><h2 id="外部命令" tabindex="-1">外部命令 <a class="header-anchor" href="#外部命令" aria-label="Permalink to &quot;外部命令&quot;">​</a></h2><ul><li><p>编辑文件: <code>vim filename</code>。</p></li><li><p>查看文件: <code>cat filename</code>。</p></li></ul><h2 id="其它命令" tabindex="-1">其它命令 <a class="header-anchor" href="#其它命令" aria-label="Permalink to &quot;其它命令&quot;">​</a></h2><ul><li><p>重复上次命令: <code>.</code>。</p></li><li><p>内容缩进: <code>shift + &gt;</code>为左缩进，<code>shift + &lt;</code>为右缩进。</p></li><li><p>行号显隐: <code>:set number</code>；<code>:set nonumber</code>为隐藏行号。</p></li><li><p>语法高亮: <code>:syntax on</code>；<code>:syntax off</code>为关闭语法高亮。</p></li></ul>',31)])])}const m=o(l,[["render",a]]);export{u as __pageData,m as default};
